Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=('3d050b87c0471d70f33b55ed2a7f1401f31480b30d3bec6accc1e1f5b2df92a9',), event=Authored(todo='localwrites', at=datetime(2026, 11, 22, 3, 58, 41, 481203), actor='bmabsout', kind='suzateryTodo', created=datetime(2026, 11, 1, 0, 0, 0), body="Every page write (a message, a rename, a tap) is a signed content-addressed object the tab appends to its own replica and draws at once, synced to the box like reads; the box's acceptance, refusal and each effect's completion come back as receipt objects, effects run at most once per request hash, and independent effects run in parallel. No page write waits on a round trip.", spec=Flat(value=0.5), rationale=('A CRDT needs no round trip: a write is drawn at once, and its effects are idempotent state updates.',), category='', waiting_on='', detail="In work on 2026-11-20: the follow-up to stage 3 is in review. Left after it: the tab writes Again, and the measures.\n\nState on 2026-11-20: the follow-up to stage 3 is accepted and on a train. Left: the tab writes Again, and the measures; with them, a seal answers at its keep (the signing after it goes), the scene of a writer's send waits for the empty box, and the law of two tabs over one row also holds that a refusal with words is ruled until the person acts.\n\nState on 2026-11-20: the follow-up to stage 3 has landed and is deployed (release 2.1.189); the readings of the stores were the same before and after.\n\nIn work on 2026-11-21: the end of stage 3: the tab writes Again as its own line and the two routes go, a seal answers at its keep, the reviews' leftovers, and the stage's measures.\n\nState on 2026-11-21: the end of stage 3 is up and reviewed with two reads, and sent back for two faults of an edit: the edited question lost its files, and the box could take the rewind and refuse the new question, leaving neither. Accepted: the tab's own Again line, the rule's refusals, the seal as one step, the two routes gone.\n\nState on 2026-11-22: stage 3 landed with release 2.1.204. The tab itself writes an edit and a regenerate (an Again line and, for an edit, its own question, sealed in one move), a seal answers at once, and the box's edit and regenerate routes are gone; the least client version rose to 16. One question decides whether an edit is taken up (the fold, the outline and the digest ask the same one), and a generated law over two tabs and the box holds it, a split pair included. What remains: the topic stores' write still signs as a second step and becomes one step as the lines' did; a named kind for an edit's question would close the one stated limit (a second device whose clock repeats the edit's exact instant); the taps and the settings writes are not yet local writes.", source=None, subtodos=(), notes=(), note=''))